function redact(value) {
  return String(value ?? '')
    .replace(/\b(?:Bearer\s+)[A-Za-z0-9._~+\/-]+=*/gi, '[REDACTED_TOKEN]')
    .replace(/\b(?:sk-[A-Za-z0-9_-]{12,}|xox[baprs]-[A-Za-z0-9-]+|eyJ[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+)\b/g, '[REDACTED_TOKEN]')
    .replace(/\b(?:password|passwd|api[_ -]?key|secret|access[_ -]?token)\s*[:=]\s*[^\s,;]+/gi, '[REDACTED_SECRET]')
    .replace(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi, '[REDACTED_EMAIL]')
    .replace(/\b(?:\d[ -]*?){13,19}\b/g, '[REDACTED_NUMBER]')
    .replace(/(?:\+\d{1,3}[ -]?)?(?:\(?\d{3}\)?[ -])\d{3}[ -]\d{4}\b/g, '[REDACTED_PHONE]')
    .replace(/https?:\/\/\S+/gi, '[REDACTED_URL]')
    .replace(/[\u0000-\u0008\u000b\u000c\u000e-\u001f]/g, '');
}

function validate(schema, value, path = 'result') {
  if (schema.type === 'object') {
    if (!value || Array.isArray(value) || typeof value !== 'object') throw new Error(`${path}: expected object`);
    for (const key of schema.required) if (!(key in value)) throw new Error(`${path}.${key}: required`);
    for (const key of Object.keys(value)) {
      if (!(key in schema.properties)) throw new Error(`${path}.${key}: unexpected field`);
      validate(schema.properties[key], value[key], `${path}.${key}`);
    }
  } else if (schema.type === 'array') {
    if (!Array.isArray(value) || value.length > schema.maxItems) throw new Error(`${path}: invalid array`);
    value.forEach((v, i) => validate(schema.items, v, `${path}[${i}]`));
  } else {
    if (typeof value !== schema.type) throw new Error(`${path}: expected ${schema.type}`);
    if (schema.enum && !schema.enum.includes(value)) throw new Error(`${path}: invalid option`);
    if (schema.type === 'number' && (!Number.isFinite(value) || value < schema.minimum || value > schema.maximum)) throw new Error(`${path}: outside limits`);
    if (schema.type === 'string' && value.length > schema.maxLength) throw new Error(`${path}: too long`);
  }
}

function cleanTree(value) {
  if (typeof value === 'string') return redact(value);
  if (Array.isArray(value)) return value.map(cleanTree);
  if (value && typeof value === 'object') return Object.fromEntries(Object.entries(value).map(([k, v]) => [k, cleanTree(v)]));
  return value;
}

function validateConfig(row) {
  const c = row?.config;
  if (!c || !row.tenant_id) throw new Error('Run database.sql and configure the default deployment.');
  if (!/^[a-z0-9][a-z0-9-]{1,61}[a-z0-9]$/.test(c.zendeskSubdomain) || c.zendeskSubdomain === 'configure-me') throw new Error('Set zendeskSubdomain in swl_escalation.deployments.');
  if (!/^https:\/\/[a-z0-9.-]+(?::[0-9]{2,5})?$/i.test(c.qdrantUrl) || /\.invalid(?::\d+)?$/.test(c.qdrantUrl)) throw new Error('Set an HTTPS qdrantUrl without path, credentials or query.');
  if (!/^[A-Za-z0-9_-]{1,80}$/.test(c.collection)) throw new Error('Invalid vector collection.');
  if (!/^[A-Za-z0-9._-]{1,100}$/.test(c.model)) throw new Error('Invalid model.');
  if (!/^[CG][A-Z0-9]{8,}$/.test(c.slackChannelId) || c.slackChannelId === 'C+1234567890') throw new Error('Set the private Slack review channel ID.');
  if (!Number.isInteger(c.approvalMinutes) || c.approvalMinutes < 5 || c.approvalMinutes > 240) throw new Error('approvalMinutes must be 5-240.');
  if (!Number.isFinite(c.minConfidence) || c.minConfidence < 0.5 || c.minConfidence > 1) throw new Error('minConfidence must be 0.5-1.');
  if (!Number.isFinite(c.vectorThreshold) || c.vectorThreshold < 0 || c.vectorThreshold > 1) throw new Error('Invalid vectorThreshold.');
  for (const key of ['inputUsdPerMillion', 'cachedInputUsdPerMillion', 'outputUsdPerMillion', 'embeddingUsdPerMillion']) {
    if (c[key] !== null && (!Number.isFinite(c[key]) || c[key] < 0)) throw new Error(`Invalid ${key}`);
  }
  return {tenantId: row.tenant_id, config: c};
}

function intake(body) {
  if (!body || Array.isArray(body) || typeof body !== 'object') return {valid: false, reason: 'Expected a JSON object.'};
  if (Object.keys(body).some(k => !['eventId', 'ticketId'].includes(k))) return {valid: false, reason: 'Only eventId and ticketId are accepted.'};
  if (typeof body.eventId !== 'string' || !/^[A-Za-z0-9][A-Za-z0-9._:-]{0,119}$/.test(body.eventId)) return {valid: false, reason: 'eventId must be a stable source-event identifier, max 120 characters.'};
  const ticketId = String(body.ticketId ?? '');
  if (!/^[1-9][0-9]{0,14}$/.test(ticketId)) return {valid: false, reason: 'ticketId must be a positive Zendesk ticket ID.'};
  return {valid: true, eventId: body.eventId, ticketId};
}

function ticketSnapshot(ticket, comments, expectedId) {
  if (!ticket || String(ticket.id) !== expectedId || !Number.isFinite(Date.parse(ticket.updated_at))) throw new Error('Invalid Zendesk ticket response.');
  if (!Array.isArray(comments)) throw new Error('Invalid Zendesk comments response.');
  return {
    id: expectedId, updatedAt: ticket.updated_at,
    subject: redact(ticket.subject).slice(0, 300), status: String(ticket.status),
    organizationId: ticket.organization_id ? String(ticket.organization_id) : '',
    priority: ['low', 'normal', 'high', 'urgent'].includes(ticket.priority) ? ticket.priority : 'normal',
    messages: comments.filter(c => c.public === true).slice(0, 10).map(c => ({
      id: String(c.id), createdAt: String(c.created_at), body: redact(c.plain_body ?? c.body).slice(0, 1600),
    })).reverse(),
  };
}

function cacheSnapshot(value, ticket, tenantId) {
  try {
    const v = typeof value === 'string' ? JSON.parse(value) : value;
    return v?.tenantId === tenantId && v?.ticket?.id === String(ticket.id) && v.ticket.updatedAt === ticket.updated_at && Array.isArray(v.ticket.messages) ? v.ticket : null;
  } catch { return null; }
}

function evidence(response, tenantId, threshold) {
  if (!Array.isArray(response?.result?.points)) throw new Error('Invalid Qdrant query response.');
  return response.result.points.filter(p => p.payload?.tenant_id === tenantId && p.payload?.approved === true && ['policy', 'resolved_case'].includes(p.payload.kind) && Number(p.score) >= threshold)
    .slice(0, 5).map(p => ({id: String(p.id), kind: p.payload.kind, title: redact(p.payload.title).slice(0, 160), text: redact(p.payload.text).slice(0, 1600), similarity: p.score}));
}

function parseAgent(role, schema, response, ctx) {
  const choice = response?.choices?.[0];
  if (!choice || choice.finish_reason !== 'stop' || choice.message?.refusal || typeof choice.message?.content !== 'string') throw new Error(`${role}: refused, incomplete or invalid response.`);
  const result = JSON.parse(choice.message.content);
  validate(schema, result);
  const rawRefs = role === 'research' ? result.evidence.map(e => String(e.id)) : (result.evidenceIds ?? []).map(String);
  const allowed = new Set(role === 'research' ? ctx.documents.map(d => d.id) : (ctx.agents.research?.evidence ?? []).map(e => e.id));
  if (rawRefs.some(id => !allowed.has(id))) throw new Error(`${role}: unsupported evidence reference.`);
  const cleaned = cleanTree(result);
  if (role === 'research') cleaned.evidence.forEach((e, i) => { e.id = rawRefs[i]; });
  if (Array.isArray(cleaned.evidenceIds)) cleaned.evidenceIds = rawRefs;
  const safetyChanged = JSON.stringify(cleaned) !== JSON.stringify(result);
  const u = response.usage;
  if (!u || !Number.isInteger(u.prompt_tokens) || !Number.isInteger(u.completion_tokens) || u.prompt_tokens < 0 || u.completion_tokens < 0) throw new Error(`${role}: missing usage.`);
  const cached = Math.min(u.prompt_tokens, Math.max(0, Number(u.prompt_tokens_details?.cached_tokens) || 0));
  const c = ctx.config;
  const priced = [c.inputUsdPerMillion, c.cachedInputUsdPerMillion, c.outputUsdPerMillion].every(Number.isFinite);
  const usage = {role, responseId: String(response.id ?? ''), model: String(response.model ?? c.model), inputTokens: u.prompt_tokens, cachedTokens: cached, outputTokens: u.completion_tokens,
    estimatedUsd: priced ? ((u.prompt_tokens - cached) * c.inputUsdPerMillion + cached * c.cachedInputUsdPerMillion + u.completion_tokens * c.outputUsdPerMillion) / 1e6 : null};
  return {...ctx, agents: {...ctx.agents, [role]: cleaned}, safetyChanged: Boolean(ctx.safetyChanged || safetyChanged), lastUsage: usage};
}

function gate(ctx) {
  const {triage: t, research: r, decision: d, action: a, reviewer: q} = ctx.agents;
  const reasons = [];
  if (!ctx.ticket.messages.length) reasons.push('No public conversation.');
  if (['solved', 'closed', 'deleted'].includes(ctx.ticket.status)) reasons.push('Ticket is no longer actionable.');
  if (!r.grounded || !r.evidence.length || !d.evidenceIds.length || !a.evidenceIds.length) reasons.push('Missing supporting evidence.');
  if (r.gaps.length) reasons.push('Research has unresolved evidence gaps.');
  if (!q.pass || q.concerns.length || q.unsupportedClaims.length) reasons.push('Reviewer did not clear the proposal.');
  if (Math.min(t.confidence, d.confidence, q.confidence) < ctx.config.minConfidence) reasons.push('Confidence below configured threshold.');
  if (d.recommendation === 'manual_review' || t.category === 'security') reasons.push('Specialist review required.');
  if (ctx.safetyChanged) reasons.push('Generated output required redaction.');
  if (!a.privateNote.trim() || !a.followUpSteps.length) reasons.push('Empty action plan.');
  const note = ['Smart Workflow Lab escalation review', `Case: ${ctx.caseId}`, `Risk score: ${d.riskScore}/100 (heuristic, not churn probability)`, '', a.privateNote, '', 'Follow-up:', ...a.followUpSteps.map((s, i) => `${i + 1}. ${s}`), '', `Evidence: ${a.evidenceIds.join(', ')}`].join('\n');
  return {...ctx, eligible: reasons.length === 0, gateReasons: reasons,
    action: {privateNote: note, priority: a.priority, marker: `SWL-CASE:${ctx.caseId}`}};
}

function slackEscape(text) { return String(text).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); }

function approvalText(ctx) {
  return slackEscape([
    `Approval required | ticket ${ctx.ticketId} | case ${ctx.caseId}`,
    `Recommendation: ${ctx.agents.decision.recommendation}; risk ${ctx.agents.decision.riskScore}/100`,
    `Proposed priority: ${ctx.action.priority} (never lowered).`,
    'Approve adds the following PRIVATE note. No customer email is sent.', '',
    ctx.action.privateNote, '', `Marker: ${ctx.action.marker}`,
    `Expires after ${ctx.config.approvalMinutes} minutes. Reject leaves the ticket unchanged.`,
    'Approval links grant permission to whoever holds the link; keep this review channel private.',
  ].join('\n'));
}

function approvedResponse(value) { return value?.data?.approved === true; }

function prepareWrite(ctx, fresh) {
  const ticket = fresh?.ticket;
  if (!ticket || String(ticket.id) !== ctx.ticketId) throw new Error('Unexpected Zendesk ticket.');
  if (ticket.updated_at !== ctx.ticket.updatedAt) return {...ctx, safeToWrite: false, stopReason: 'Ticket changed while awaiting approval.'};
  if (['solved', 'closed', 'deleted'].includes(ticket.status)) return {...ctx, safeToWrite: false, stopReason: 'Ticket is no longer actionable.'};
  const levels = ['low', 'normal', 'high', 'urgent'];
  const current = levels.includes(ticket.priority) ? ticket.priority : 'normal';
  const priority = levels[Math.max(levels.indexOf(current), levels.indexOf(ctx.action.priority))];
  return {...ctx, safeToWrite: true, writeBody: {ticket: {
    safe_update: true, updated_stamp: ticket.updated_at, priority,
    comment: {body: `${ctx.action.privateNote}\n\n[${ctx.action.marker}]`, public: false},
  }}};
}

function verifyWrite(response, ctx) {
  if (String(response?.ticket?.id) !== ctx.ticketId) throw new Error('Unconfirmed ticket update; reconcile before replay.');
  const found = response?.audit?.events?.some(e => e.type === 'Comment' && e.public === false && String(e.body).includes(`[${ctx.action.marker}]`));
  if (!found) throw new Error('Missing private-note audit marker; reconcile before replay.');
  return {...ctx, auditId: String(response.audit.id)};
}

function feedbackInput(body) {
  if (!body || typeof body !== 'object' || Array.isArray(body)) return {valid: false, reason: 'Expected a JSON object.'};
  if (Object.keys(body).some(k => !['eventId', 'caseId', 'outcome', 'summary', 'approvedForMemory'].includes(k))) return {valid: false, reason: 'Unexpected feedback fields.'};
  if (typeof body.eventId !== 'string' || !/^[A-Za-z0-9][A-Za-z0-9._:-]{0,119}$/.test(body.eventId)) return {valid: false, reason: 'Invalid eventId.'};
  if (!/^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(body.caseId ?? '')) return {valid: false, reason: 'Invalid caseId UUID.'};
  if (!['retained', 'churned', 'resolved'].includes(body.outcome) || typeof body.summary !== 'string' || body.summary.trim().length < 20 || body.summary.length > 3000 || body.approvedForMemory !== true) return {valid: false, reason: 'Supply outcome, 20-3000 character summary, and approvedForMemory=true after human review.'};
  return {valid: true, eventId: body.eventId, caseId: body.caseId, outcome: body.outcome, summary: redact(body.summary)};
}

function embedding(response) {
  const vector = response?.data?.[0]?.embedding;
  if (!Array.isArray(vector) || vector.length !== 1536 || vector.some(v => !Number.isFinite(v))) throw new Error('Expected a 1536-dimensional embedding.');
  return vector;
}

return [{json:intake($json.body)}];

