function validate(schema, value, path = 'result') {
  if (schema.type === 'object') {
    if (!value || Array.isArray(value) || typeof value !== 'object') throw new Error(`${path}: expected object`);
    for (const key of schema.required) if (!(key in value)) throw new Error(`${path}.${key}: required`);
    for (const key of Object.keys(value)) {
      if (!(key in schema.properties)) throw new Error(`${path}.${key}: unexpected field`);
