    if (!Array.isArray(value) || value.length > schema.maxItems) throw new Error(`${path}: invalid array`);
    value.forEach((v, i) => validate(schema.items, v, `${path}[${i}]`));
  } else {
    if (typeof value !== schema.type) throw new Error(`${path}: expected ${schema.type}`);
    if (schema.enum && !schema.enum.includes(value)) throw new Error(`${path}: invalid option`);
    if (schema.type === 'number' && (!Number.isFinite(value) || value < schema.minimum || value > schema.maximum)) throw new Error(`${path}: outside limits`);
