  return {...ctx, agents: {...ctx.agents, [role]: cleaned}, safetyChanged: Boolean(ctx.safetyChanged || safetyChanged), lastUsage: usage};
}

function gate(ctx) {
  const {triage: t, research: r, decision: d, action: a, reviewer: q} = ctx.agents;
  const reasons = [];
  if (!ctx.ticket.messages.length) reasons.push('No public conversation.');
  if (['solved', 'closed', 'deleted'].includes(ctx.ticket.status)) reasons.push('Ticket is no longer actionable.');
  if (!r.grounded || !r.evidence.length || !d.evidenceIds.length || !a.evidenceIds.length) reasons.push('Missing supporting evidence.');
  if (r.gaps.length) reasons.push('Research has unresolved evidence gaps.');
  if (!q.pass || q.concerns.length || q.unsupportedClaims.length) reasons.push('Reviewer did not clear the proposal.');
  if (Math.min(t.confidence, d.confidence, q.confidence) < ctx.config.minConfidence) reasons.push('Confidence below configured threshold.');
  if (d.recommendation === 'manual_review' || t.category === 'security') reasons.push('Specialist review required.');
  if (ctx.safetyChanged) reasons.push('Generated output required redaction.');
  if (!a.privateNote.trim() || !a.followUpSteps.length) reasons.push('Empty action plan.');
