WITH done AS (
UPDATE swl_escalation.feedback SET status='indexed',embedding_tokens=$3::int,estimated_usd=$4::numeric,updated_at=now()
WHERE id=$1::uuid AND execution_id=$2 AND status='processing' RETURNING case_id
) UPDATE swl_escalation.cases SET status='resolved',updated_at=now()
WHERE id IN (SELECT case_id FROM done) RETURNING id;

